package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerEmailException;

/**
 * Rejects a create-owner request whose lower-cased email is already used by any existing owner.
 * Runs after {@link ValidateNewOwner} has normalized the request's email to its lower-cased form
 * (see {@link OwnerEmail}), and before {@link BuildOwner}, so a duplicate is a 409 rather than a
 * persisted record. Each stored owner's email is lower-cased the same way before comparing. A
 * request without an email supplies nothing to conflict with and is left alone.
 */
public class CheckOwnerEmailUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerEmailException {
        String email = lower(request.getEmail());
        if (email == null) {
            return;
        }
        for (Owner owner : ownerRepository.findAll()) {
            if (email.equals(lower(owner.getEmail()))) {
                throw new DuplicateOwnerEmailException(request.getEmail());
            }
        }
    }

    private static String lower(String email) {
        if (email == null || email.isBlank()) {
            return null;
        }
        return email.trim().toLowerCase(Locale.ROOT);
    }
}
===== CheckOwnerHouseholdUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerHouseholdException;

/**
 * Rejects a create-owner request whose last name and address both match an existing owner (a
 * shared household): the last name is compared case-insensitively with collapsed whitespace and the
 * address by its normalized form (see {@link OwnerAddress}). Runs after
 * {@link ValidateNewOwner} has published the request, and before {@link BuildOwner}, so a
 * duplicate is a 409 rather than a persisted record. The request opts out by setting
 * {@code sharesHousehold} true, in which case the check is skipped.
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = OwnerAddress.normalize(request.getAddress());
        for (Owner owner : ownerRepository.findAll()) {
            if (lastName.equals(normalize(owner.getLastName()))
                    && address.equals(OwnerAddress.normalize(owner.getAddress()))) {
                throw new DuplicateOwnerHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }

    /** Lower-case and collapse all runs of whitespace to a single space, trimmed. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== BuildOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        LocalDate effective = owner.getRegistrationDate();
        if (effective == null) {
            effective = LocalDate.now();
        }
        // Registration must fall on a business day: a supplied or defaulted weekend date rolls
        // forward to the next Monday, and later steps derive their values from the adjusted date.
        owner.setRegistrationDate(BusinessDay.rollForward(effective));
        built.set(owner);
    }
}
