20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateOwnerEmailException {
22	        String email = lower(request.getEmail());
23	        if (email == null) {
24	            return;
25	        }
26	        for (Owner owner : ownerRepository.findAll()) {
27	            if (email.equals(lower(owner.getEmail()))) {
28	                throw new DuplicateOwnerEmailException(request.getEmail());
29	            }
30	        }
31	    }
