13	/**
14	 * First step of {@code POST /api/owners}. Normalizes the address to its canonical form (see
15	 * {@link OwnerAddress}) and stores it back on the request, then rejects a request that is missing
16	 * or blank in any required field (firstName, lastName, address, city, telephone) — the address
17	 * being tested for blankness after normalization — with a 400 whose body lists the offending field
18	 * names. Then normalizes the telephone to E.164 form (see {@link
19	 * TelephoneE164}), storing the E.164 value back on the request so later steps persist and return
20	 * it; a telephone that cannot form valid E.164 is rejected with a 400. Runs before {@link
21	 * BuildOwner} maps the body to an {@link org.springframework.samples.petclinic.model.Owner}.
22	 */
23	public class ValidateNewOwner {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
26	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
27	        request.setAddress(OwnerAddress.normalize(request.getAddress()));
28	        List<String> missing = new ArrayList<>();
29	        if (isBlank(request.getFirstName())) {
30	            missing.add("firstName");
31	        }
32	        if (isBlank(request.getLastName())) {
33	            missing.add("lastName");
34	        }
35	        if (isBlank(request.getAddress())) {
36	            missing.add("address");
37	        }
38	        if (isBlank(request.getCity())) {
39	            missing.add("city");
40	        }
41	        if (isBlank(request.getTelephone())) {
42	            missing.add("telephone");
43	        }
44	        if (!missing.isEmpty()) {
45	            throw new MissingOwnerFieldsException(missing);
46	        }
47	        request.setTelephone(TelephoneE164.normalize(request.getTelephone()));
48	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
