1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Shared normalization for an owner's {@code address}, applied whenever an owner is created.
8	 * Leading and trailing whitespace is trimmed and every internal run of whitespace is collapsed
9	 * to a single space; the result is upper-cased; and common street-type abbreviations are expanded
10	 * as whole words: {@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}. So {@code
11	 * "  12  main  st "} becomes {@code "12 MAIN STREET"}.
12	 *
13	 * <p>The normalized value is what is stored and returned, what the required-field check tests for
14	 * blankness, and the form every address comparison uses (household duplicate detection and the
15	 * shared household id).
16	 */
17	final class OwnerAddress {
18	
19	    /** Any run of whitespace, collapsed to a single space. */
20	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
21	
22	    /** Whole-word abbreviations expanded to their canonical street type (keys are upper-case). */
23	    private static final Map<String, String> ABBREVIATIONS = Map.of(
24	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
25	
26	    private OwnerAddress() {
27	    }
28	
29	    /**
30	     * Returns the normalized address for the given raw value, or {@code ""} when {@code null}.
31	     * A value that is empty or only whitespace normalizes to {@code ""}.
32	     */
33	    static String normalize(String address) {
34	        if (address == null) {
35	            return "";
36	        }
37	        String collapsed = WHITESPACE.matcher(address.trim()).replaceAll(" ");
38	        if (collapsed.isEmpty()) {
39	            return "";
40	        }
41	        String[] tokens = collapsed.toUpperCase().split(" ");
42	        StringBuilder sb = new StringBuilder(collapsed.length());
43	        for (int i = 0; i < tokens.length; i++) {
44	            if (i > 0) {
45	                sb.append(' ');
46	            }
47	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
48	        }
49	        return sb.toString();
50	    }
51	}
