5	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
6	
7	/**
8	 * Shared normalization for an owner's optional {@code email}. When absent (null or blank) the
9	 * email is left unset; when present it must be a syntactically valid address and is stored and
10	 * returned lower-cased. An invalid address is rejected with 400 via {@link InvalidEmailException}.
11	 */
12	final class OwnerEmail {
13	
14	    /** Syntactic address check: non-empty local part, one '@', and a dotted domain. */
15	    private static final Pattern EMAIL = Pattern.compile(
16	            "^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
17	
18	    private OwnerEmail() {
19	    }
20	
21	    /**
22	     * Returns the normalized (lower-cased) email, or {@code null} when none was supplied.
23	     *
24	     * @throws InvalidEmailException when an email is present but not syntactically valid.
25	     */
26	    static String normalize(String email) throws InvalidEmailException {
27	        if (email == null || email.isBlank()) {
28	            return null;
29	        }
30	        String trimmed = email.trim();
31	        if (!EMAIL.matcher(trimmed).matches()) {
32	            throw new InvalidEmailException(email);
33	        }
34	        return trimmed.toLowerCase();
35	    }
36	}
