4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	
14	/**
15	 * Assigns a shared {@code householdId} when a create-owner request opts into a shared household
16	 * with {@code sharesHousehold} true and there is already an owner with the same last name and
17	 * address (the last name compared case-insensitively with collapsed whitespace and the address by
18	 * its normalized form, see {@link OwnerAddress}). The identifier is stable: derived
19	 * deterministically from the normalized last name and address, so every owner in the same
20	 * household receives the same value. It is also written back onto the existing same-household
21	 * owners so both sides of the join carry the identifier. Runs after {@link BuildOwner} has produced
22	 * the {@link Owner} and before {@link SaveOwner} persists it, so the new owner is saved with the id.
23	 *
24	 * <p>When {@code sharesHousehold} is not set, or there is no existing same-household owner, no
25	 * identifier is assigned and the owner is saved without one.
26	 */
27	public class AssignHousehold {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
30	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            return;
32	        }
33	        String lastName = normalize(request.getLastName());
34	        String address = OwnerAddress.normalize(request.getAddress());
35	        List<Owner> household = new ArrayList<>();
36	        String existingId = null;
37	        for (Owner other : ownerRepository.findAll()) {
38	            if (lastName.equals(normalize(other.getLastName()))
39	                    && address.equals(OwnerAddress.normalize(other.getAddress()))) {
40	                household.add(other);
41	                if (other.getHouseholdId() != null && !other.getHouseholdId().isBlank()) {
42	                    existingId = other.getHouseholdId();
43	                }
44	            }
45	        }
46	        if (household.isEmpty()) {
47	            return;
48	        }
49	        String householdId = (existingId != null) ? existingId : deriveHouseholdId(lastName, address);
50	        owner.setHouseholdId(householdId);
51	        for (Owner other : household) {
52	            if (!householdId.equals(other.getHouseholdId())) {
53	                other.setHouseholdId(householdId);
54	                ownerRepository.save(other);
55	            }
56	        }
57	    }
58	
59	    /** Deterministic 16-char upper-hex identifier over the normalized last name and address. */
60	    private static String deriveHouseholdId(String lastName, String address) {
61	        try {
62	            byte[] digest = MessageDigest.getInstance("SHA-256")
63	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
64	            StringBuilder sb = new StringBuilder(16);
65	            for (int i = 0; i < 8; i++) {
66	                sb.append(String.format("%02X", digest[i]));
67	            }
68	            return sb.toString();
69	        }
70	        catch (NoSuchAlgorithmException ex) {
71	            throw new IllegalStateException("SHA-256 unavailable", ex);
72	        }
73	    }
74	
75	    /** Lower-case and collapse all runs of whitespace to a single space, trimmed. */
76	    private static String normalize(String value) {
77	        if (value == null) {
78	            return "";
79	        }
80	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
81	    }
82	}
